    const el = railRef.current
    if (!el) return
    setRailH(el.clientHeight)
    const ro = new ResizeObserver(([e]) => setRailH(e.contentRect.height))
    ro.observe(el)
    const onWheel = (e) => {
      const sc = scrollerRef?.current
      if (!sc) return
      e.preventDefault()
      sc.scrollTop += e.deltaY
    }
